import { expect, test } from '@playwright/test';

// API/session/search rights below are synthetic. Media bytes are real AAC/FLAC
// generated by native-music-setup through the existing production processor.
// No media methods, browser prototypes, promises from play(), or clocks change.
test.use({ serviceWorkers: 'block' });

const releaseId = '71000000-0000-4000-8000-000000000001';
const releaseVersionId = '72000000-0000-4000-8000-000000000001';
const trackId = (i) => `73000000-0000-4000-8000-00000000000${i}`;
const recordingId = (i) => `74000000-0000-4000-8000-00000000000${i}`;
const assetId = (i, q) => `75000000-0000-4000-8000-0000000000${i}${q}`;
const qualities = ['low', 'high', 'lossless'];
const titles = ['Introducción nativa A', 'Constelación nativa B'];
const releaseTitle = 'Dos pistas sintéticas';
const slug = 'dos-pistas-sinteticas';
const queryA = 'introduccion';
const queryB = 'constelacion';
const observed = new WeakMap();

async function prepareSearch(page, baseURL, { holdQueryA = false } = {}) {
  const fixture = JSON.parse(process.env.TDF_NATIVE_MUSIC_FIXTURE);
  const appOrigin = new URL(baseURL).origin;
  const apiOrigin = 'http://127.0.0.1:19099';
  const mediaOrigin = new URL(fixture.endpoint).origin;
  const state = { searches: [], assetAccess: [], details: [],
    mediaRequests: [], blockedExternal: [], unexpectedWrites: [], pageErrors: [],
    queryACompletion: null, lateAResponse: null, playbackEvents: [],
    mediaProvenance: { masterSha256: fixture.masterSha256, files: fixture.files,
      identityBoundary: 'first/second URLs share the existing generated master; track identity is verified by exact UUID, authorized asset IDs and source URL, not audible song recognition.' },
    boundary: 'Synthetic API/search/permissions; real loopback derivatives and native media events. No production authorization or physical-device claim.' };
  const tracks = [1, 2].map((i) => ({ trackId: trackId(i), recordingId: recordingId(i),
    title: titles[i - 1], displayArtist: 'Artista sintético TDF', durationMs: 24000,
    sources: qualities.map((quality, q) => ({ assetId: assetId(i, q), role: 'stream_audio',
      mediaType: fixture.files[quality].mediaType,
      technicalMetadata: { bitrate_kbps: [96, 256, 0][q], loudness_lufs: -14 } })),
  }));
  const summary = { id: releaseId, versionId: releaseVersionId, versionNumber: 1,
    artistPartyId: 101, slug, kind: 'album', title: releaseTitle, displayArtist: 'Artista sintético TDF',
    releaseAtUtc: '2026-09-13T00:00:00Z', publishedAt: '2026-09-13T00:00:01Z', labelName: null, coverAssetId: null };
  const release = { ...summary, subtitle: null, versionTitle: null, catalogNumber: null,
    explicitContent: 'not_explicit', originalReleaseDate: '2026-09-13', coverAssets: [],
    tracks: tracks.map((track, i) => ({ ...track, discNumber: 1, trackNumber: i + 1, explicitContent: 'not_explicit' })),
    availability: [{ ruleId: '76000000-0000-4000-8000-000000000001', trackId: null,
      territoryMode: 'include', territories: ['EC'], startsAt: null, endsAt: null,
      listeningPolicy: 'full', downloadPolicy: 'none', purchasable: false, priceMinor: null, currency: null }],
  };
  const hit = (i) => ({ ...tracks[i - 1], releaseId, releaseVersionId,
    releaseSlug: slug, releaseTitle });
  let revoked = false;
  let releaseLateA = () => {};
  const gate = new Promise((resolve) => { releaseLateA = resolve; });
  page.on('pageerror', (error) => state.pageErrors.push(error.message));
  for (const event of ['requestfinished', 'requestfailed']) page.on(event, (request) => {
    const url = new URL(request.url());
    if (url.pathname === '/music/search' && url.searchParams.get('q') === queryA) state.queryACompletion = event;
  });
  await page.addInitScript(() => {
    localStorage.setItem('tdf-hq-ui/locale', 'es');
    globalThis.__searchNativeEvents = [];
    globalThis.__searchSelections = [];
    window.addEventListener('tdf-player-load-track', ({ detail }) => {
      globalThis.__searchSelections.push({ id: detail.track.id, title: detail.track.title,
        recordingId: detail.track.recordingId, releaseId: detail.track.releaseId,
        releaseVersionId: detail.track.releaseVersionId,
        sourceAssetIds: detail.track.sources.map((source) => source.assetId) });
    });
    for (const type of ['playing', 'pause', 'timeupdate', 'seeking', 'seeked', 'error', 'loadedmetadata']) document.addEventListener(type, (event) => {
      if (event.target instanceof HTMLAudioElement) globalThis.__searchNativeEvents.push({
        type, trusted: event.isTrusted, time: event.target.currentTime, source: event.target.currentSrc,
      });
    }, true);
  });
  await page.route('**/*', async (route) => {
    const request = route.request(), url = new URL(request.url());
    if (!['http:', 'https:'].includes(url.protocol)) return route.continue();
    // Check origin before any API matching, including external telemetry POSTs.
    if (![appOrigin, apiOrigin, mediaOrigin].includes(url.origin)) {
      state.blockedExternal.push(url.origin); return route.abort('blockedbyclient');
    }
    if (url.origin === mediaOrigin) {
      state.mediaRequests.push({ path: url.pathname, range: request.headers().range ?? null });
      return route.continue();
    }
    if (!['fetch', 'xhr'].includes(request.resourceType())) return url.origin === appOrigin
      ? route.continue() : route.abort('blockedbyclient');
    const path = url.pathname.replace(/^\/api(?=\/)/, '');
    if (path === '/music/playback-events' && request.method() === 'POST') {
      state.playbackEvents.push(request.postDataJSON()); return route.fulfill({ status: 202, json: { accepted: true } });
    }
    if (request.method() !== 'GET') {
      state.unexpectedWrites.push({ method: request.method(), path });
      return route.fulfill({ status: 405, json: { error: 'No synthetic business mutations allowed' } });
    }
    if (path === '/session') return route.fulfill({ json: null });
    if (path === '/health') return route.fulfill({ json: { status: 'ok', db: 'ok' } });
    if (path === '/catalogs/batch') return route.fulfill({ json: {} });
    if (path.startsWith('/catalogs/')) return route.fulfill({ json: { items: [], catalogs: [], defaults: [] } });
    if (path === '/fans/artists' || path === '/directory/suggestions') return route.fulfill({ json: [] });
    if (path === '/directory/taxonomies') return route.fulfill({ json: { locale: 'es', professions: [],
      classifiedCategories: [], compensationTypes: [], serviceOfferings: [], currencies: [], instruments: [], genres: [], cities: [] } });
    if (path === '/directory/search') return route.fulfill({ json: { items: [], sponsoredItems: [],
      facets: { entityTypes: {}, cities: [], total: 0 }, nextCursor: null } });
    if (path === '/music/search') {
      const q = url.searchParams.get('q') ?? '';
      state.searches.push({ q, limit: url.searchParams.get('limit'), offset: url.searchParams.get('offset') });
      if (holdQueryA && q === queryA) {
        await gate;
        try { await route.fulfill({ json: [hit(1)] }); state.lateAResponse = 'fulfilled'; }
        catch (error) { state.lateAResponse = `not delivered: ${String(error.message)}`; }
        return;
      }
      return route.fulfill({ json: q === queryB ? [hit(2)] : q === queryA ? [hit(1)] : [] });
    }
    if (path === '/music/releases') return route.fulfill({ json: [summary] });
    if (path === `/music/releases/${slug}`) { state.details.push(slug); return route.fulfill({ json: release }); }
    const id = path.match(/^\/music\/assets\/([^/]+)\/access$/)?.[1];
    if (id) {
      state.assetAccess.push(id);
      for (const i of [1, 2]) for (const [q, quality] of qualities.entries()) if (id === assetId(i, q)) {
        if (revoked && i === 2) return route.fulfill({ status: 403, json: { error: 'Synthetic permission revoked after search' } });
        return route.fulfill({ json: { ...fixture.files[quality],
          url: `${fixture.endpoint}/media/${i === 1 ? 'first' : 'second'}/${quality}`,
          expiresAt: new Date(Date.now() + 600000).toISOString(), acceptRanges: true } });
      }
      return route.fulfill({ status: 404, json: { error: 'Unknown synthetic asset' } });
    }
    return route.fulfill({ status: 404, json: { error: 'Unconfigured synthetic API route' } });
  });
  observed.set(page, state);
  return { state, fixture, releaseLateA, revoke: () => { revoked = true; } };
}

const resultRegion = (page) => page.getByRole('region', { name: 'Resultados musicales', exact: true });
const playB = (page) => resultRegion(page).getByRole('button', { name: `Reproducir ${titles[1]}`, exact: true });

async function expectNoSelection(page, state) {
  expect(state.assetAccess).toEqual([]);
  expect(state.mediaRequests).toEqual([]);
  expect(await page.evaluate(() => globalThis.__searchSelections)).toEqual([]);
  expect(await page.locator('audio').evaluateAll((elements) => elements.every((audio) => audio.paused && !audio.getAttribute('src')))).toBe(true);
}

test.afterEach(async ({ page }, testInfo) => {
  const state = observed.get(page);
  if (!state || page.isClosed()) return;
  const native = await page.evaluate(() => ({ events: globalThis.__searchNativeEvents,
    selections: globalThis.__searchSelections,
    audio: [...document.querySelectorAll('audio')].map((audio) => ({ source: audio.currentSrc,
      time: audio.currentTime, paused: audio.paused, error: audio.error?.code ?? null })) }));
  await testInfo.attach('music-search-native-boundary.json', {
    body: JSON.stringify({ ...state, ...native }, null, 2), contentType: 'application/json' });
});

test('@critical @mobile-flow PW-MUSIC-SEARCH-NATIVE-01 plays the exact matched recording and retains its real decoder across release navigation', async ({ page, baseURL }) => {
  const { state } = await prepareSearch(page, baseURL);
  await page.goto(`/buscar?q=${queryB}`, { waitUntil: 'domcontentloaded' });
  await expect(playB(page)).toBeVisible();
  expect(state.details).toEqual([]);
  await expectNoSelection(page, state);
  const link = () => resultRegion(page).getByRole('link', { name: `Ver lanzamiento ${releaseTitle}`, exact: true });
  await link().click();
  await expect(page).toHaveURL(new RegExp(`/musica/${slug}$`));
  await expect(page.getByRole('heading', { name: releaseTitle, exact: true, level: 1 })).toBeVisible();
  await expectNoSelection(page, state); // Opening a release must not start its first track A.
  await page.goBack();
  await expect(playB(page)).toBeVisible();
  await expectNoSelection(page, state);
  await playB(page).focus();
  await playB(page).press('Enter');
  const player = page.getByRole('region', { name: 'Reproductor global' });
  const audio = page.locator('audio');
  await expect(player.getByText(titles[1], { exact: true })).toBeVisible();
  await expect(audio).toHaveCount(1);
  await expect.poll(() => audio.evaluate((element) => !element.paused && !element.error && element.currentTime > 0.5),
    { message: 'Matched B must advance real AAC playback', timeout: 15000 }).toBe(true);
  await expect.poll(() => audio.evaluate((element) => element.currentSrc)).toMatch(/\/media\/second\/high$/);
  expect(state.assetAccess).toEqual([assetId(2, 1)]);
  expect(await page.evaluate(() => globalThis.__searchSelections.map(({ id }) => id))).toEqual([trackId(2)]);
  await audio.evaluate((element) => { globalThis.__searchOriginalAudio = element; });
  const before = await audio.evaluate((element) => element.currentTime);
  await link().click();
  await expect(page).toHaveURL(new RegExp(`/musica/${slug}$`));
  expect(await audio.evaluate((element) => element === globalThis.__searchOriginalAudio)).toBe(true);
  await expect.poll(() => audio.evaluate((element) => element.currentTime)).toBeGreaterThan(before + 0.5);
  await expect.poll(() => audio.evaluate((element) => element.currentSrc)).toMatch(/\/media\/second\/high$/);
  await player.getByRole('button', { name: 'Opciones de reproducción', exact: true }).click();
  const options = page.getByRole('dialog', { name: 'Opciones de reproducción', exact: true });
  await options.getByRole('combobox', { name: 'Calidad de audio', exact: true }).click();
  await page.getByRole('option', { name: 'Lossless', exact: true }).click();
  await expect.poll(() => audio.evaluate((element) => element.currentSrc)).toMatch(/\/media\/second\/lossless$/);
  // Measure advancement after restoration, so the seek itself cannot count as
  // decoded playback. These are observed native events, with no media mocks.
  await expect.poll(() => page.evaluate(() => globalThis.__searchNativeEvents.some((event) =>
    event.type === 'seeked' && event.trusted && event.source.endsWith('/media/second/lossless')))).toBe(true);
  const losslessStart = await audio.evaluate((element) => element.currentTime);
  await expect.poll(() => audio.evaluate((element, start) => !element.paused && !element.error && element.currentTime > start + 0.3, losslessStart)).toBe(true);
  await options.getByRole('button', { name: 'Cerrar opciones', exact: true }).click();
  expect(await audio.evaluate((element) => element === globalThis.__searchOriginalAudio)).toBe(true);
  expect(state.assetAccess).toEqual([assetId(2, 1), assetId(2, 2)]);
  expect(state.unexpectedWrites).toEqual([]);
  expect(state.pageErrors).toEqual([]);
});

test('@critical @mobile-flow PW-MUSIC-SEARCH-NATIVE-02 late query A cannot replace B and revoked B never plays the release intro', async ({ page, baseURL }) => {
  const fixture = await prepareSearch(page, baseURL, { holdQueryA: true });
  const { state } = fixture;
  try {
    await page.goto(`/buscar?q=${queryA}`, { waitUntil: 'domcontentloaded' });
    await expect.poll(() => state.searches.some(({ q }) => q === queryA)).toBe(true);
    const query = page.getByRole('combobox', { name: 'Buscar artistas, profesionales o eventos', exact: true });
    await query.fill(queryB);
    await query.press('Enter');
    await expect(playB(page)).toBeVisible();
    await expectNoSelection(page, state);
    fixture.revoke(); // Search metadata can outlive authorization; delivery must fail closed.
    await playB(page).click();
    const player = page.getByRole('region', { name: 'Reproductor global', exact: true });
    await expect(player.getByText(titles[1], { exact: true })).toBeVisible();
    await expect(player.getByRole('status')).toHaveText('El servidor no autorizó una fuente vigente para esta pista.');
    fixture.releaseLateA();
    await expect.poll(() => state.lateAResponse).not.toBeNull();
    await expect.poll(() => state.queryACompletion).not.toBeNull();
    expect(state.lateAResponse === 'fulfilled' || state.queryACompletion === 'requestfailed').toBe(true);
    // Request completion plus real animation frames let delivered query data
    // reach React. If AbortSignal wins, the attached receipt says so explicitly.
    await page.evaluate(() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))));
    await expect(playB(page)).toBeVisible();
    await expect(resultRegion(page).getByRole('button', { name: `Reproducir ${titles[0]}`, exact: true })).toHaveCount(0);
    await expect(player.getByText(titles[1], { exact: true })).toBeVisible();
    await expect(player.getByRole('button', { name: 'Pausar', exact: true })).toHaveCount(0);
    expect(await page.evaluate(() => globalThis.__searchSelections.map(({ id }) => id))).toEqual([trackId(2)]);
    expect(state.assetAccess).toHaveLength(qualities.length); // One bounded pass over B's candidates.
    expect(state.assetAccess.every((id) => qualities.some((_, q) => id === assetId(2, q)))).toBe(true);
    expect(state.details).toEqual([]);
    expect(state.mediaRequests).toEqual([]);
    expect(await page.locator('audio').evaluateAll((elements) => elements.every((audio) => audio.paused && !audio.getAttribute('src')))).toBe(true);
    expect(state.unexpectedWrites).toEqual([]);
    expect(state.pageErrors).toEqual([]);
  } finally { fixture.releaseLateA(); }
});
